arguments.command:
cat > /tmp/git-askpass.sh <<'EOF'
#!/bin/sh
case "$1" in
*Username*) echo "x-access-token" ;;
*Password*) echo "$GITHUB_TOKEN" ;;
*) echo "" ;;
esac
EOF
chmod +x /tmp/git-askpass.sh
GIT_ASKPASS=/tmp/git-askpass.sh git -C /tmp/friends-monica-worktree push origin HEAD:refs/heads/friend/monica
